import 'package:cloud_firestore/cloud_firestore.dart';
import 'model_utils.dart';
class NotificationModel { const NotificationModel({required this.id,required this.userId,required this.title,required this.body,required this.createdAt,this.readAt,this.data=const {}}); final String id,userId,title,body; final DateTime createdAt; final DateTime? readAt; final Map<String,String> data; factory NotificationModel.fromFirestore(DocumentSnapshot<Map<String,Object?>> d)=>NotificationModel(id:d.id,userId:d['userId'] as String,title:d['title'] as String,body:d['body'] as String,createdAt:dateFromValue(d['createdAt'])!,readAt:dateFromValue(d['readAt']),data:Map<String,String>.from(d['data'] as Map? ?? {})); Map<String,Object?> toFirestore()=>{'userId':userId,'title':title,'body':body,'createdAt':Timestamp.fromDate(createdAt),'readAt':timestampFromDate(readAt),'data':data}; }
